<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{AdvertisingCampaign,Advertiser,AdPlacement}; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Inertia\Inertia;
class AdvertisingCampaignController extends Controller { public function index(){return Inertia::render('Admin/Advertising/Campaigns/Index',['campaigns'=>AdvertisingCampaign::with(['advertiser','placements'])->withCount('creatives')->latest()->get()]);} public function create(){return $this->form();} public function store(Request $r){$d=$this->data($r);$d['uuid']=(string)Str::uuid();$d['public_code']='AD-'.now()->format('ym').'-'.Str::upper(Str::random(6));$c=AdvertisingCampaign::create($d);$c->placements()->sync($r->input('placement_ids',[]));return to_route('admin.ad-campaigns.index')->with('success','Advertising campaign created.');} public function show(AdvertisingCampaign $adCampaign){return Inertia::render('Admin/Advertising/Campaigns/Show',['campaign'=>$adCampaign->load(['advertiser','placements','creatives','approver'])]);} public function edit(AdvertisingCampaign $adCampaign){return $this->form($adCampaign);} public function update(Request $r,AdvertisingCampaign $adCampaign){$adCampaign->update($this->data($r));$adCampaign->placements()->sync($r->input('placement_ids',[]));return to_route('admin.ad-campaigns.show',$adCampaign)->with('success','Advertising campaign updated.');} public function submit(AdvertisingCampaign $adCampaign){abort_unless(in_array($adCampaign->status,['draft','rejected']),422);$adCampaign->update(['status'=>'submitted','submitted_at'=>now(),'rejection_reason'=>null]);return back()->with('success','Campaign submitted for approval.');} public function approve(Request $r,AdvertisingCampaign $adCampaign){$r->validate(['decision'=>'required|in:approve,reject','rejection_reason'=>'required_if:decision,reject|nullable|string|max:2000']); if($r->decision==='approve')$adCampaign->update(['status'=>'approved','approved_at'=>now(),'approved_by'=>$r->user()->id,'rejection_reason'=>null]);else $adCampaign->update(['status'=>'rejected','approved_at'=>null,'approved_by'=>$r->user()->id,'rejection_reason'=>$r->rejection_reason]);return back()->with('success','Campaign decision recorded.');} private function form(?AdvertisingCampaign $c=null){return Inertia::render('Admin/Advertising/Campaigns/Form',['campaign'=>$c?->load('placements'),'advertisers'=>Advertiser::where('status','active')->orderBy('name')->get(['id','name']),'placements'=>AdPlacement::where('is_active',true)->orderBy('name')->get()]);} private function data(Request $r):array{return $r->validate(['advertiser_id'=>'required|exists:advertisers,id','name'=>'required|string|max:255','objective'=>'required|in:awareness,traffic,conversion,sponsorship','pricing_model'=>'required|in:flat,cpm,cpc,sponsorship','budget_cents'=>'required|integer|min:0','contract_value_cents'=>'required|integer|min:0','impression_goal'=>'nullable|integer|min:0','click_goal'=>'nullable|integer|min:0','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','internal_notes'=>'nullable|string|max:5000','placement_ids'=>'array','placement_ids.*'=>'exists:ad_placements,id']);} }
